parameters.query:
SELECT
    COUNT(*) AS total_leads,
    COUNT(*) FILTER (
        WHERE created_at >= CURRENT_DATE
    ) AS new_leads,
    COUNT(*) FILTER (
        WHERE LOWER(lead_status) = 'qualified'
    ) AS qualified_leads,
    COUNT(*) FILTER (
        WHERE LOWER(lead_status) = 'converted'
    ) AS converted_leads,
    ROUND(AVG(lead_score), 2) AS average_lead_score
FROM lead_qualification;

parameters.jsCode:
const stats = $items("PostgreSQL Report Data")[0].json;
const leads = $items("Supabase Leads").map(item => item.json);

const totalLeads = Number(stats.total_leads || 0);
const newLeads = Number(stats.new_leads || 0);
const qualifiedLeads = Number(stats.qualified_leads || 0);
const convertedLeads = Number(stats.converted_leads || 0);
const averageLeadScore = Number(stats.average_lead_score || 0);

// Top lead source
const sourceCounts = {};

for (const lead of leads) {
  const source = lead.source || "Unknown";
  sourceCounts[source] = (sourceCounts[source] || 0) + 1;
}

const topLeadSource =
  Object.entries(sourceCounts)
    .sort((a, b) => b[1] - a[1])[0]?.[0] || "N/A";

// Top 5 leads
const top5Leads = [...leads]
  .sort(
    (a, b) =>
      Number(b.lead_score || 0) - Number(a.lead_score || 0)
  )
  .slice(0, 5)
  .map(lead => ({
    name: lead.name,
    company: lead.company,
    source: lead.source,
    lead_score: Number(lead.lead_score || 0),
    lead_status: lead.lead_status
  }));

// Conversion rate
const conversionRate = totalLeads
  ? Number(((convertedLeads / totalLeads) * 100).toFixed(1))
  : 0;

return [
  {
    json: {
      totalLeads,
      newLeads,
      qualifiedLeads,
      convertedLeads,
      averageLeadScore,
      topLeadSource,
      conversionRate,
      top5Leads
    }
  }
];
